(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(PaymentsComponent, [{
    type: Component,
    args: [{ selector: "app-payments", standalone: false, template: `<div class="pagetitle d-flex justify-content-between align-items-center">
  <div>
    <h1>Payments Management</h1>
    <nav>
      <ol class="breadcrumb mb-0">
        <li class="breadcrumb-item"><a routerLink="/">Home</a></li>
        <li class="breadcrumb-item">Reservations</li>
        <li class="breadcrumb-item active">Payments</li>
      </ol>
    </nav>
  </div>
  <div *ngIf="activeTab === 'collect'" class="d-flex align-items-center bg-white rounded-pill px-4 py-2 shadow-sm border">
    <label class="fw-bold me-3 text-muted small text-uppercase mb-0">Select Date:</label>
    <input type="text" mwlFlatpickr [altInput]="true" altFormat="d/m/Y" dateFormat="Y-m-d" class="form-control border-0 fw-bold text-primary p-0 bg-transparent" [(ngModel)]="selectedDate" style="outline: none; box-shadow: none;">
  </div>
</div>

<div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-4 mt-3">
  <div class="d-flex gap-2">
    <button class="btn px-4 py-2 fw-bold rounded-pill transition-all"
      [class.btn-primary]="activeTab === 'collect'"
      [class.btn-light]="activeTab !== 'collect'"
      (click)="activeTab = 'collect'">
      <i class="bi bi-wallet2 me-2"></i>Collect Payments
    </button>
    <button class="btn px-4 py-2 fw-bold rounded-pill transition-all"
      [class.btn-primary]="activeTab === 'records'"
      [class.btn-light]="activeTab !== 'records'"
      (click)="activeTab = 'records'">
      <i class="bi bi-journal-text me-2"></i>Payment Records
    </button>
  </div>
</div>

<!-- SECTION 1: Collect Payments View -->
<section class="section" *ngIf="activeTab === 'collect'">
  <!-- Flight Time Groups -->
  <div class="row g-4">
    <div class="col-md-6 col-xl-4" *ngFor="let group of groupedReservations; let i = index">
      <div class="card h-100 shadow-sm border-0" style="border-top: 4px solid var(--bs-primary) !important;">
        <!-- Group Header -->
        <div class="card-header bg-white border-bottom-0 pt-4 pb-0">
          <div class="d-flex justify-content-between align-items-center">
            <h5 class="card-title text-dark mb-0 fw-bold">
              <i class="bi bi-clock me-2 text-primary"></i>{{ group.flightTime.time }}
            </h5>
            <span class="badge bg-primary bg-opacity-10 text-primary rounded-pill px-3">
              {{ group.reservations.length }} Reservations
            </span>
          </div>
        </div>
        
        <!-- Group Body (Reservations) -->
        <div class="card-body pt-3">
          <div class="d-flex flex-column gap-3">
            <div *ngIf="group.reservations.length === 0" class="text-center py-4 text-muted small bg-light rounded border border-dashed">
              No flights scheduled for this slot.
            </div>
            
            <div *ngFor="let res of group.reservations" 
                 class="p-3 rounded border bg-white shadow-sm position-relative payment-card cursor-pointer transition-all"
                 [ngClass]="{'border-danger bg-danger bg-opacity-10': res.status === 2}"
                 (click)="openPaymentModal(res)"
                 style="cursor: pointer;">
                 
              <div class="d-flex justify-content-between align-items-start mb-2">
                <h6 class="fw-bold mb-0 text-dark">{{ res.title || 'Untitled Reservation' }}</h6>
                <span class="badge bg-secondary">#{{ res.id }}</span>
              </div>
              
              <div class="d-flex justify-content-between align-items-center small text-muted">
                <div><i class="bi bi-people-fill me-1"></i> {{ getPassengersCount(res) }} Passengers</div>
                <div class="fw-bold text-primary">{{ res.totalAmount | number:'1.2-2' }} {{ getCurrencyCode(res.preferredCurrency) }}</div>
              </div>
              
              <div class="mt-2 d-flex justify-content-between align-items-center">
                <div>
                  <span *ngIf="res.status === 2" class="badge bg-danger text-white">
                    <i class="bi bi-x-circle-fill me-1"></i> Cancelled
                  </span>
                </div>
                <div>
                  <span *ngIf="res.status !== 2 && isFullyPaid(res)" class="badge bg-success text-white border border-success py-1 px-2">
                    <i class="bi bi-check-circle-fill me-1"></i> Paid
                  </span>
                  <span *ngIf="res.status !== 2 && !isFullyPaid(res)" class="badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 py-1 px-2">
                    <i class="bi bi-wallet2 me-1"></i> Make Payment
                  </span>
                  <span *ngIf="res.status === 2 && getAmountPaidForRes(res) > 0" class="badge bg-warning text-dark py-1 px-2">
                    <i class="bi bi-arrow-counterclockwise me-1"></i> Issue Refund
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- SECTION 2: Payment Records View -->
<section class="section" *ngIf="activeTab === 'records'">
  <!-- Advanced Metrics Grid -->
  <div class="row g-4 mb-4">
    <div class="col-md-3">
      <div class="card shadow-sm border-0 border-start border-primary border-4 p-3 bg-white h-100">
        <div class="text-muted small fw-bold text-uppercase">TRY Collected</div>
        <div class="h2 fw-bold text-primary mt-2 mb-0">{{ getFilteredTotal(0) | number:'1.2-2' }} \u20BA</div>
      </div>
    </div>
    <div class="col-md-3">
      <div class="card shadow-sm border-0 border-start border-success border-4 p-3 bg-white h-100">
        <div class="text-muted small fw-bold text-uppercase">USD Collected</div>
        <div class="h2 fw-bold text-success mt-2 mb-0">{{ getFilteredTotal(1) | number:'1.2-2' }} $</div>
      </div>
    </div>
    <div class="col-md-3">
      <div class="card shadow-sm border-0 border-start border-warning border-4 p-3 bg-white h-100">
        <div class="text-muted small fw-bold text-uppercase">EUR Collected</div>
        <div class="h2 fw-bold text-warning mt-2 mb-0">{{ getFilteredTotal(2) | number:'1.2-2' }} \u20AC</div>
      </div>
    </div>
    <div class="col-md-3">
      <div class="card shadow-sm border-0 border-start border-info border-4 p-3 bg-white h-100">
        <div class="text-muted small fw-bold text-uppercase">GBP Collected</div>
        <div class="h2 fw-bold text-info mt-2 mb-0">{{ getFilteredTotal(3) | number:'1.2-2' }} \xA3</div>
      </div>
    </div>
  </div>

  <!-- Advanced Filters Bar -->
  <div class="card shadow-sm border-0 mb-4 bg-white">
    <div class="card-body p-4">
      <h5 class="fw-bold mb-3 text-dark"><i class="bi bi-funnel-fill me-2 text-primary"></i>Filters</h5>
      <div class="row g-3 align-items-end">
        <div class="col-md-3">
          <label class="form-label small fw-bold text-muted">Start Date</label>
          <input type="text" mwlFlatpickr [altInput]="true" altFormat="d/m/Y" dateFormat="Y-m-d" class="form-control" [(ngModel)]="filterStartDate">
        </div>
        <div class="col-md-3">
          <label class="form-label small fw-bold text-muted">End Date</label>
          <input type="text" mwlFlatpickr [altInput]="true" altFormat="d/m/Y" dateFormat="Y-m-d" class="form-control" [(ngModel)]="filterEndDate">
        </div>
        <div class="col-md-2">
          <label class="form-label small fw-bold text-muted">Payment Method</label>
          <select class="form-select" [(ngModel)]="filterMethod">
            <option value="all">All Methods</option>
            <option value="0">Cash</option>
            <option value="1">Card</option>
            <option value="2">Transfer/IBAN</option>
          </select>
        </div>
        <div class="col-md-2">
          <label class="form-label small fw-bold text-muted">Currency</label>
          <select class="form-select" [(ngModel)]="filterCurrency">
            <option value="all">All Currencies</option>
            <option value="0">TRY (\u20BA)</option>
            <option value="1">USD ($)</option>
            <option value="2">EUR (\u20AC)</option>
            <option value="3">GBP (\xA3)</option>
          </select>
        </div>
        <div class="col-md-2 d-flex gap-2">
          <button class="btn btn-secondary w-100 py-2 rounded" (click)="filterStartDate=''; filterEndDate=''; filterMethod='all'; filterCurrency='all'; filterSearch=''">
            <i class="bi bi-arrow-counterclockwise"></i> Reset
          </button>
        </div>
      </div>
      <div class="row g-3 mt-2">
        <div class="col-12">
          <div class="input-group mb-0">
            <span class="input-group-text bg-light border-end-0"><i class="bi bi-search"></i></span>
            <input type="text" class="form-control border-start-0 ps-0" placeholder="Search by Reservation ID, Title, or Passenger Name..." [(ngModel)]="filterSearch">
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Payment Records Table -->
  <div class="card shadow-sm border-0 bg-white">
    <div class="card-body p-4">
      <div class="d-flex justify-content-between align-items-center mb-3">
        <h5 class="fw-bold text-dark mb-0"><i class="bi bi-list-stars me-2 text-primary"></i>Transactions ({{ filteredTransactions.length }})</h5>
      </div>
      
      <div class="table-responsive">
        <table class="table table-hover align-middle border-0">
          <thead class="table-light">
            <tr>
              <th class="border-0">Date</th>
              <th class="border-0">Reservation</th>
              <th class="border-0">Passengers</th>
              <th class="border-0">Amount Paid</th>
              <th class="border-0">Method</th>
              <th class="border-0">Notes</th>
              <th class="border-0 text-center">Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngIf="filteredTransactions.length === 0">
              <td colspan="7" class="text-center py-5 text-muted bg-light rounded border border-dashed">
                <i class="bi bi-inbox fs-2 d-block mb-2 text-muted"></i>
                No transaction records found matching your filters.
              </td>
            </tr>
            <tr *ngFor="let record of filteredTransactions" [ngClass]="{'bg-danger bg-opacity-10': record.isUnpaid}">
              <td class="fw-bold">{{ record.paymentDate | date:'dd/MM/yyyy HH:mm' }}</td>
              <td>
                <div class="fw-bold text-dark">
                  <a href="javascript:void(0)" (click)="editReservation(record.reservationId)" class="text-decoration-none text-dark" title="Edit Reservation">
                    {{ getReservationTitle(record.reservationId) }} <i class="bi bi-box-arrow-up-right ms-1 small text-primary"></i>
                  </a>
                </div>
                <span class="badge bg-secondary" style="cursor: pointer;" (click)="editReservation(record.reservationId)" title="Edit Reservation">#{{ record.reservationId }}</span>
                <span *ngIf="getReservationAgency(record.reservationId)" class="badge bg-primary ms-1" title="Agency"><i class="bi bi-building me-1"></i>{{ getReservationAgency(record.reservationId) }}</span>
                <span *ngIf="record.isDeposit" class="badge bg-info text-dark ms-1">Deposit</span>
                <span *ngIf="record.isUnpaid" class="badge bg-danger text-white ms-1">Non Paid</span>
              </td>
              <td class="text-muted small">{{ getReservationPassengers(record.reservationId) || 'N/A' }}</td>
              <td class="fw-bold fs-6" [ngClass]="{
                'text-danger': record.isUnpaid || record.amount < 0,
                'text-success': !record.isUnpaid && record.amount >= 0 && record.currency === 1,
                'text-warning': !record.isUnpaid && record.amount >= 0 && record.currency === 2,
                'text-info': !record.isUnpaid && record.amount >= 0 && record.currency === 3,
                'text-primary': !record.isUnpaid && record.amount >= 0 && record.currency === 0
              }">
                <span *ngIf="record.amount < 0">-</span>{{ (record.amount < 0 ? -record.amount : record.amount) | number:'1.2-2' }} {{ getCurrencyCode(record.currency) }}
                <span *ngIf="record.amount < 0" class="badge bg-danger bg-opacity-10 text-danger border border-danger border-opacity-25 small ms-1">Refund</span>
              </td>
              <td>
                <span *ngIf="record.isDeposit" class="badge bg-info bg-opacity-10 text-info border border-info border-opacity-25 px-3 py-2 rounded-pill">
                  \u{1F4B0} Deposit ({{ record.method === 1 ? 'Card' : (record.method === 2 ? 'Transfer' : 'Cash') }})
                </span>
                <span *ngIf="record.isUnpaid" class="badge bg-danger bg-opacity-10 text-danger border border-danger border-opacity-25 px-3 py-2 rounded-pill">
                  \u274C Non Paid
                </span>
                <span *ngIf="!record.isDeposit && !record.isUnpaid">
                  <span *ngIf="record.method === 0" class="badge bg-success bg-opacity-10 text-success border border-success border-opacity-25 px-3 py-2 rounded-pill">
                    \u{1F4B5} Cash
                  </span>
                  <span *ngIf="record.method === 1" class="badge bg-primary bg-opacity-10 text-primary border border-primary border-opacity-25 px-3 py-2 rounded-pill">
                    \u{1F4B3} Card
                  </span>
                  <span *ngIf="record.method === 2" class="badge bg-info bg-opacity-10 text-info border border-info border-opacity-25 px-3 py-2 rounded-pill">
                    \u{1F3E6} Transfer
                  </span>
                </span>
              </td>
              <td class="text-muted small" style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                {{ record.notes || '-' }}
              </td>
              <td class="text-center">
                <button class="btn btn-sm btn-outline-success border-0 fw-bold me-1" (click)="openPaymentForRecord(record)" [disabled]="isRecordFullyPaid(record)" title="Pay">
                  Pay
                </button>
                <button class="btn btn-sm btn-outline-primary border-0 rounded-circle me-1" (click)="printThermalBill(record.reservationId)" title="Print Thermal Bill (80mm)">
                  <i class="bi bi-printer fs-5"></i>
                </button>
                <button class="btn btn-sm btn-outline-danger border-0 rounded-circle" (click)="deletePaymentRecord(record.id!)" *ngIf="!record.isDeposit && !record.isUnpaid" title="Delete Payment">
                  <i class="bi bi-trash fs-5"></i>
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</section>

<!-- Payment Modal -->
<div class="modal fade" id="paymentModal" tabindex="-1" aria-hidden="true">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content border-0 shadow-lg" *ngIf="selectedReservation">
      <div class="modal-header text-white border-0" [ngClass]="{'bg-danger': isRefundMode, 'bg-primary': !isRefundMode}">
        <h5 class="modal-title">
          {{ isRefundMode ? 'Issue Refund' : 'Payment' }} for #{{ selectedReservation.id }} - {{ selectedReservation.title || 'Untitled' }}
        </h5>
        <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Close"></button>
      </div>
      
      <form (ngSubmit)="savePayment()" #paymentForm="ngForm">
        <div class="modal-body p-4 bg-light">
          <!-- Refund Warning Alert -->
          <div *ngIf="isRefundMode" class="alert alert-danger d-flex align-items-center mb-3">
            <i class="bi bi-exclamation-triangle-fill me-2 fs-5"></i>
            <div>
              This reservation is <strong>CANCELLED</strong>. You can issue a refund for up to <strong>{{ amountPaid | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</strong>.
            </div>
          </div>
          
          <!-- Balance Summary -->
          <div class="row text-center mb-4 g-2">
            <div class="col-3">
              <div class="bg-white p-2 rounded shadow-sm border">
                <div class="small text-muted text-uppercase fw-bold" style="font-size: 0.65rem;">Total</div>
                <div class="fw-bold text-dark fs-6">{{ totalAmountDue | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</div>
              </div>
            </div>
            <div class="col-3">
              <div class="bg-white p-2 rounded shadow-sm border">
                <div class="small text-muted text-uppercase fw-bold" style="font-size: 0.65rem;">Deposit</div>
                <div class="fw-bold text-info fs-6">{{ selectedReservation.deposit || 0 | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</div>
              </div>
            </div>
            <div class="col-3">
              <div class="bg-white p-2 rounded shadow-sm border">
                <div class="small text-muted text-uppercase fw-bold" style="font-size: 0.65rem;">Paid</div>
                <div class="fw-bold text-success fs-6">{{ amountPaid | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</div>
              </div>
            </div>
            <div class="col-3">
              <div class="bg-white p-2 rounded shadow-sm border">
                <div class="small text-muted text-uppercase fw-bold" style="font-size: 0.65rem;">Rest</div>
                <div class="fw-bold text-danger fs-6">{{ remainingBalance | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</div>
              </div>
            </div>
          </div>

          <!-- Payment Form -->
          <div class="bg-white p-3 rounded shadow-sm border">
            <div class="row">
              <div class="col-md-7 mb-3">
                <label class="form-label fw-bold d-flex justify-content-between">
                  <span>{{ isRefundMode ? 'Refund Amount' : 'Amount' }} ({{ getCurrencyCode(currentPayment.currency) }}) <span class="text-danger">*</span></span>
                  <a href="javascript:void(0)" class="small text-primary text-decoration-none" (click)="setPayAll()">{{ isRefundMode ? 'Refund All' : 'Pay All' }}</a>
                </label>
                <div class="input-group">
                  <span class="input-group-text"><i class="bi" [ngClass]="{'bi-arrow-counterclockwise text-danger': isRefundMode, 'bi-wallet2': !isRefundMode}"></i></span>
                  <input type="number" class="form-control" [(ngModel)]="amountInPayCurrency" (ngModelChange)="onAmountInPayCurrencyChange()" name="amount" required>
                </div>
              </div>
              <div class="col-md-5 mb-3">
                <label class="form-label fw-bold">Pay in Currency</label>
                <select class="form-select" [(ngModel)]="currentPayment.currency" name="currency" (ngModelChange)="onCurrencyChange($event)">
                  <option *ngFor="let opt of currencyOptions" [ngValue]="opt.value">{{ opt.label }}</option>
                </select>
              </div>
            </div>

            <!-- Manual Exchange Overrides (shown only when payment currency !== reservation preferred currency) -->
            <div class="row g-2 mb-3 p-3 rounded border bg-light" *ngIf="selectedReservation && currentPayment.currency !== (selectedReservation.preferredCurrency !== undefined && selectedReservation.preferredCurrency !== null ? selectedReservation.preferredCurrency : 1)">
              <div class="col-md-6">
                <label class="form-label fw-bold small text-muted">Exchange Rate</label>
                <div class="input-group input-group-sm">
                  <span class="input-group-text bg-white">1 {{ getCurrencyCode(selectedReservation.preferredCurrency) }} =</span>
                  <input type="number" class="form-control" [(ngModel)]="exchangeRate" (ngModelChange)="onExchangeRateChange()" name="exchangeRate" step="0.0001" min="0.0001" required>
                  <span class="input-group-text bg-white">{{ getCurrencyCode(currentPayment.currency) }}</span>
                </div>
              </div>
              <div class="col-md-6">
                <label class="form-label fw-bold small text-muted">Equivalent in {{ getCurrencyCode(selectedReservation.preferredCurrency) }}</label>
                <div class="input-group input-group-sm">
                  <input type="number" class="form-control" [(ngModel)]="convertedAmount" (ngModelChange)="onConvertedAmountChange()" name="convertedAmount" required>
                  <span class="input-group-text bg-white">{{ getCurrencyCode(selectedReservation.preferredCurrency) }}</span>
                </div>
              </div>
              <div class="col-12 text-center mt-2 small text-muted">
                Conversion: {{ amountInPayCurrency || 0 | number:'1.2-2' }} {{ getCurrencyCode(currentPayment.currency) }} pays off {{ convertedAmount || 0 | number:'1.2-2' }} {{ getCurrencyCode(selectedReservation.preferredCurrency) }} of reservation balance.
              </div>
            </div>

            <div class="row">
              <div class="col-md-6 mb-3">
                <label class="form-label fw-bold">Method</label>
                <select class="form-select" [(ngModel)]="currentPayment.method" name="method">
                  <option *ngFor="let opt of methodOptions" [ngValue]="opt.value">{{ opt.label }}</option>
                </select>
              </div>
              <div class="col-md-6 mb-3">
                <label class="form-label fw-bold">Date</label>
                <input type="datetime-local" class="form-control" [(ngModel)]="currentPayment.paymentDate" name="paymentDate" required>
              </div>
            </div>

            <div class="mb-2">
              <label class="form-label fw-bold">Notes</label>
              <textarea class="form-control" [(ngModel)]="currentPayment.notes" name="notes" rows="2" placeholder="Add any extra payment details..."></textarea>
            </div>
          </div>
          
        </div>
        <div class="modal-footer border-0 p-4 pt-0 bg-light">
          <button type="button" class="btn btn-secondary px-4" data-bs-dismiss="modal">Cancel</button>
          <button type="submit" class="btn px-4 shadow-sm" [ngClass]="{'btn-danger': isRefundMode, 'btn-primary': !isRefundMode}" [disabled]="!paymentForm.form.valid || amountInPayCurrency <= 0 || (isRefundMode && convertedAmount > amountPaid)">
            {{ isRefundMode ? 'Confirm Refund' : 'Confirm Payment' }}
          </button>
        </div>
      </form>
    </div>
  </div>
</div>

` }]
  }], () => [{ type: PaymentService }, { type: ReservationService }, { type: FlightTimeService }, { type: CurrencyService }, { type: PilotService }, { type: AgencyService }, { type: FlightPackageService }, { type: ActivatedRoute }, { type: Router }], null);
})();
