(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(FlightTimesComponent, [{
    type: Component,
    args: [{ selector: "app-flight-times", standalone: false, template: `<div class="pagetitle">
  <h1>Flight Time Management</h1>
  <nav>
    <ol class="breadcrumb">
      <li class="breadcrumb-item"><a routerLink="/">Home</a></li>
      <li class="breadcrumb-item active">Flight Times</li>
    </ol>
  </nav>
</div>

<section class="section">
  <div class="row">
    <!-- List Column -->
    <div class="col-lg-8">
      <div class="card shadow-sm border-0">
        <div class="card-body">
          <h5 class="card-title">Available Time Slots</h5>
          
          <div *ngIf="isLoading" class="text-center py-5">
            <div class="spinner-border text-primary" role="status">
              <span class="visually-hidden">Loading...</span>
            </div>
          </div>

          <div class="table-responsive" *ngIf="!isLoading">
            <table class="table table-hover align-middle">
              <thead class="bg-light">
                <tr>
                  <th class="ps-4">Time Slot</th>
                  <th>Status</th>
                  <th class="text-end pe-4">Actions</th>
                </tr>
              </thead>
              <tbody>
                <tr *ngFor="let item of flightTimes">
                  <td class="ps-4 fw-bold text-primary">{{ item.time }}</td>
                  <td>
                    <span class="badge rounded-pill" [ngClass]="item.isActive ? 'bg-success' : 'bg-danger'">
                      {{ item.isActive ? 'Active' : 'Inactive' }}
                    </span>
                  </td>
                  <td class="text-end pe-4">
                    <button class="btn btn-outline-primary btn-sm me-2" (click)="onEdit(item)">
                      <i class="bi bi-pencil"></i>
                    </button>
                    <button class="btn btn-outline-danger btn-sm" (click)="delete(item.id!)">
                      <i class="bi bi-trash"></i>
                    </button>
                  </td>
                </tr>
                <tr *ngIf="flightTimes.length === 0">
                  <td colspan="3" class="text-center py-4 text-muted">No flight times defined.</td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>

    <!-- Form Column -->
    <div class="col-lg-4">
      <div class="card shadow-sm border-0">
        <div class="card-body">
          <h5 class="card-title">{{ isEditing ? 'Edit Time Slot' : 'Add New Slot' }}</h5>
          
          <form (ngSubmit)="save()" #timeForm="ngForm">
            <div class="mb-3">
              <label class="form-label fw-bold small">Time (e.g. 08:30)</label>
              <input type="text" class="form-control" name="time" [(ngModel)]="currentFlightTime.time" required placeholder="HH:mm">
            </div>

            <div class="mb-3">
              <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="isActive" name="isActive" [(ngModel)]="currentFlightTime.isActive">
                <label class="form-check-label small" for="isActive">Active Status</label>
              </div>
            </div>

            <div class="d-grid gap-2">
              <button type="submit" class="btn btn-primary" [disabled]="!timeForm.form.valid">
                {{ isEditing ? 'Update Slot' : 'Save Slot' }}
              </button>
              <button type="button" class="btn btn-outline-secondary" *ngIf="isEditing" (click)="resetForm()">
                Cancel Edit
              </button>
            </div>
          </form>

        </div>
      </div>

      <div class="card bg-primary text-white border-0 shadow-sm mt-4">
        <div class="card-body p-4 text-center">
          <i class="bi bi-info-circle display-4 mb-3"></i>
          <h6>Dynamic Scheduling</h6>
          <p class="small mb-0 opacity-75">
            Changes made here will immediately appear in the reservation form and filtering options.
          </p>
        </div>
      </div>
    </div>
  </div>
</section>
`, styles: ["/* src/app/pages/flight-times/flight-times.component.css */\n.transition-all {\n  transition: all 0.3s ease;\n}\n.card {\n  border-radius: 12px;\n}\n.table thead th {\n  font-size: 0.75rem;\n  text-transform: uppercase;\n  letter-spacing: 1px;\n  color: #888;\n}\n.btn-sm {\n  padding: 0.4rem 0.6rem;\n}\n/*# sourceMappingURL=flight-times.component.css.map */\n"] }]
  }], () => [{ type: FlightTimeService }], null);
})();
