      <div class="card shadow-sm border-0 mb-4 bg-primary text-white overflow-hidden" style="background: linear-gradient(135deg, #4154f1 0%, #6f42c1 100%) !important;">
        <div class="card-body p-4 position-relative">
          <i class="bi bi-lightning-charge position-absolute end-0 top-0 fs-1 opacity-25 m-3"></i>
          <h5 class="fw-bold mb-3">Quick Actions</h5>
          <div class="d-grid gap-3">
            <button routerLink="/reservations/add" class="btn btn-light text-primary fw-bold text-start p-3 rounded-3 shadow-sm border-0">
              <i class="bi bi-plus-circle-fill me-2"></i> New Reservation
            </button>
            <button routerLink="/payments" class="btn btn-light bg-opacity-10 text-white fw-bold text-start p-3 rounded-3 shadow-sm border border-white border-opacity-25 bg-white">
              <i class="bi bi-cash-stack me-2"></i> Process Payment
            </button>
            <button routerLink="/exchange-rates" class="btn btn-light bg-opacity-10 text-white fw-bold text-start p-3 rounded-3 shadow-sm border border-white border-opacity-25 bg-white">
              <i class="bi bi-currency-exchange me-2"></i> Check Exchange Rates
            </button>
          </div>
        </div>
      </div>

